# region: emit
def emit(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: fold
def fold(xs):
    return [v * v for v in xs]

# region: sift
def sift(xs, floor_=2):
    return [v for v in xs if v >= floor_]

# region: gather
def gather(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
        return out
    return out

# region: render
def render(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: digest
def digest(summary, bar=4):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return digest(render(gather(sift(fold(emit(raw))))))

